input.new_string:
# Split on whitespace, then break any over-long word into chunks of
# ``width`` characters so every word fits on a line by itself.
words = [
    word[i : i + width]
    for word in text.split()
    for i in range(0, len(word), width)
]

lines: list[str] = []
current = ""
for word in words:
    if not current:
        current = word
    elif len(current) + 1 + len(word) <= width:
        current += " " + word
    else:
        lines.append(current)
        current = word
if current:
    lines.append(current)
return lines
